<template>
  <base-layout>
    <v-toolbar
      class="grey lighten-3"
      light
      flat
      height="50"
    >
      <v-toolbar-title class="subheading">Data Pengguna</v-toolbar-title>
      <v-spacer></v-spacer>
      <div>
        <v-btn
          color="primary"
          fab
          small
          dark
          @click.stop="onAdd"
        >
          <v-icon>fa-plus</v-icon>
        </v-btn>
        <v-btn
          class="indigo"
          fab
          small
          dark
          v-show="selectedRow.length == 1"
          @click.stop="onEdit"
        >
          <v-icon>fa-pencil</v-icon>
        </v-btn>
        <v-btn
          color="error"
          fab
          small
          dark
          v-show="selectedRow.length > 0"
          @click.stop="state.isDelete = !state.isDelete"
        >
          <v-icon>fa-trash</v-icon>
        </v-btn>
        <v-btn
          color="success"
          fab
          small
          dark
          @click="state.isRefresh = !state.isRefresh"
        >
          <v-icon>fa-refresh</v-icon>
        </v-btn>
        <!-- <v-btn
          class="blue-grey"
          fab
          small
          dark
          @click="state.isDownload = !state.isDownload"
        >
          <v-icon>fa-download</v-icon>
        </v-btn> -->
      </div>
    </v-toolbar>
    <div>
      <div v-if="state.isAdd || state.isEdit">
        <add-edit-pengguna
          :data="state.isAdd ? {}: this.selectedRow[0]"
          :is-edit="state.isEdit || !state.isAdd"
          :on-cancel="onCancel"
          :on-submitted="onSubmitted"
        ></add-edit-pengguna>
      </div>
      <div v-show="!(state.isAdd || state.isEdit)">
        <v-card
          flat
          class="pa-3"
        >
          <table-view
            from-file="users"
            :is-refresh="state.isRefresh"
            :is-delete="state.isDelete"
            :is-download="state.isDownload"
            :on-select="onSelect"
            :show-number="true"
          ></table-view>
        </v-card>
      </div>
    </div>
  </base-layout>
</template>

<script>
import _ from "lodash";
import { modal } from "@/utils/modal";

import FormAddEdit from "./AddEditPengguna";

export default {
  data: () => ({
    state: {
      isAdd: false,
      isEdit: false,
      isRefresh: false,
      isDelete: false,
      isDownload: false
    },
    selectedRow: []
  }),
  methods: {
    onSelect(row) {
      this.selectedRow = row;
    },
    onAdd() {
      modal({
        name: "full-modal",
        props: {
          type: "add"
        },
        dismissable: false,
        component: FormAddEdit
      }).then(response => {
        if (response) {
          this.state.isRefresh = !this.state.isRefresh;
        }
      });
    },
    onEdit() {
      modal({
        name: "full-modal",
        props: {
          type: "edit",
          data: this.selectedRow[0]
        },
        dismissable: false,
        component: FormAddEdit
      }).then(response => {
        if (response) {
          this.state.isRefresh = !this.state.isRefresh;
        }
      });
    }
  },
  created() {},
  computed: {
    user() {
      return this.$store.state.auth.user;
    },
    deletePermission() {
      let condition = false;
      if (this.selectedRow.length === "1") {
        if (
          this.selectedRow[0].id_user !== "1" &&
          this.selectedRow[0].id_user !== this.user.idUser
        ) {
          condition = true;
        }
      }
      if (this.selectedRow.length > 1) {
        condition = true;
        const a = _.filter(
          this.selectedRow,
          o => o.id_user === "1" || o.id_user === this.user.idUser
        );
        if (a.length > 0) condition = false;
      }
      return condition;
    }
  }
};
</script>

<style lang="css" scoped>
table.table thead th,
table.table tbody td,
table.table tbody th {
  font-size: 14px !important;
}
</style>



