<template>
  <div>
    <v-toolbar
      class="indigo"
      dark
      height="50"
    >
      <v-toolbar-title>{{type=='edit' ? 'Update': 'Add'}} Users</v-toolbar-title>
      <v-spacer></v-spacer>
      <v-btn
        icon
        @click.native="cancel()"
        dark
      >
        <v-icon>close</v-icon>
      </v-btn>
    </v-toolbar>
    <v-flex>
      <v-form ref="form">
        <v-card
          flat
          class="pa-4"
        >
          <v-layout
            row
            wrap
          >
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                label="Username"
                name="Username"
                v-model="input.username"
                :error-messages="errors.collect('Username')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <select-view
                :disabled="input.idUser==='1' || input.idUser==='2'"
                placeholder="Role"
                v-model="input.role"
                from-file="roles"
                name="Role"
                :error-messages="errors.collect('Role')"
                v-validate="'required'"
              ></select-view>
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                v-if="type!=='edit'"
                label="Password"
                name="Password"
                v-model="input.password"
                :error-messages="errors.collect('Password')"
                type="password"
                v-validate="type!=='edit' ? 'required': ''"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                v-if="type!=='edit'"
                label="Konfirmasi Password"
                name="Konfirmasi Password"
                v-model="input.confirmPassword"
                :error-messages="errors.collect('Konfirmasi Password')"
                type="password"
                v-validate="type!=='edit' ? 'required|confirmed:Password': 'confirmed:Password'"
              ></v-text-field>
            </v-flex>
          </v-layout>
        </v-card>
        <v-divider></v-divider>
        <v-card
          flat
          class="pa-3"
        >
          <v-btn
            color="success"
            @click="submit()"
          >Simpan</v-btn>
          <v-btn
            color="error"
            @click="cancel()"
          >Batal</v-btn>
        </v-card>
      </v-form>
    </v-flex>
  </div>
</template>

<script>
export default {
  props: {
    type: {
      type: String
    },
    data: {
      type: Object
    }
  },
  data: () => ({
    input: {
      idUser: "",
      username: "",
      role: "",
      password: "",
      confirmPassword: ""
    }
  }),
  created() {
    if (this.type === "edit") {
      this.input = {
        idUser: this.data.id_user,
        username: this.data.username,
        role: this.data.id_role,
        password: "",
        confirmPassword: ""
      };
    }
  },
  methods: {
    submit() {
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          this.$http
            .post("base/service/executeMutation", this.usersParams)
            .then(response => {
              if (response.data.success_message) {
                this.$vuedals.close(true);
              }
            });
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    },
    cancel() {
      this.$vuedals.close(false);
    }
  },
  computed: {
    mutationType() {
      const mutationType = this.type === "edit" ? "update" : "insert";
      return mutationType;
    },
    usersData() {
      const data = {
        username: this.input.username,
        password: this.input.password,
        id_role: this.input.role,
        id_external: "-1"
      };
      if (this.input.password === "") delete data.password;
      return data;
    },
    usersParams() {
      const params = {
        id: undefined,
        type: this.mutationType,
        name: "users",
        data: this.usersData
      };
      if (this.type === "edit") params.id = this.data["id_user"];
      return params;
    }
  }
};
</script>

<style lang="css">
</style>



